"""
Academic Writer — Corpus Text Extraction

Reads a corpus of past-articles into plain text for computational style-metric
extraction. Stdlib only: .txt/.md are read directly; .docx is unzipped and its
XML runs are stripped with a regex (docx is just a zip of XML — no
python-docx dependency needed for raw text). .pdf cannot be parsed without a
third-party library, so it is skipped with a warning; the init skill's
separate qualitative-extraction step (pdfplumber, best-effort) handles PDFs.

Tracked changes and Word field instructions (TOC/HYPERLINK/PAGEREF) are
excluded. Corpus files are frequently supervisor-returned
or peer-reviewed papers, and a reviewer's inserted text is not the author's
voice: `<w:ins>` content (someone else's insertion) and `<w:del>` content
(text the author removed) are both dropped before analysis, so only the
accepted base text reaches the style fingerprint.
"""

from __future__ import annotations

import html
import re
import zipfile
from pathlib import Path

TEXT_SUFFIXES = {".txt", ".md", ".markdown"}
DOCX_SUFFIXES = {".docx"}
SKIP_SUFFIXES = {".pdf"}

_DOCX_TAG_RE = re.compile(r"<[^>]+>")
# Paragraph boundaries become blank lines: style_metrics_core.split_paragraphs
# splits on \n\s*\n, so a single newline would collapse the whole file into one
# paragraph and wreck every paragraph-level metric.
_DOCX_PARA_BREAK_RE = re.compile(r"</w:p>", re.IGNORECASE)
_DOCX_TAB_RE = re.compile(r"<w:tab\b[^>]*/>", re.IGNORECASE)
# Word field instructions (TOC, HYPERLINK \l, PAGEREF) live in <w:instrText>
# next to real <w:t> runs, so tag-stripping alone leaves the raw switches in the
# text: `TOC \h \u \z \t "Heading 1,1,Heading 2,2,..."`. Measured on a real
# corpus, 8 paragraphs of 857 carried field markup — small, but it inflates
# vocabulary and paragraph length with syntax the author never wrote, and it
# lands those table-of-contents paragraphs on the long side of the furniture
# rule, diluting exactly the signal that rule is looking for.
_DOCX_FIELD_RES = (
    re.compile(r"<w:instrText\b[^>]*>.*?</w:instrText>", re.DOTALL | re.IGNORECASE),
    re.compile(
        r"<w:delInstrText\b[^>]*>.*?</w:delInstrText>", re.DOTALL | re.IGNORECASE
    ),
)
# Tracked-change containers, stripped *with their content* before tag removal
# (after tag removal there is no <w:ins> left to find).
_DOCX_REVISION_RES = (
    re.compile(r"<w:ins\b[^>]*>.*?</w:ins>", re.DOTALL | re.IGNORECASE),
    re.compile(r"<w:del\b[^>]*>.*?</w:del>", re.DOTALL | re.IGNORECASE),
    re.compile(r"<w:moveFrom\b[^>]*>.*?</w:moveFrom>", re.DOTALL | re.IGNORECASE),
)
_MAX_REVISION_PASSES = 5


def _strip_tracked_changes(xml: str) -> str:
    """Remove <w:ins>/<w:del>/<w:moveFrom> elements and everything inside them.

    Applied repeatedly: revision containers nest (a deletion inside an
    insertion, a move inside a deletion), and a single non-greedy pass can
    leave an outer container behind.
    """
    for _ in range(_MAX_REVISION_PASSES):
        before = xml
        for pattern in _DOCX_REVISION_RES:
            xml = pattern.sub(" ", xml)
        if xml == before:
            break
    return xml


def _read_docx_text(path: Path) -> str:
    """Best-effort raw text extraction from a .docx file using only zipfile +
    regex (no python-docx dependency)."""
    with zipfile.ZipFile(path) as zf:
        xml = zf.read("word/document.xml").decode("utf-8", errors="ignore")
    # Order matters: tracked-change containers must go before tag stripping,
    # and entity unescaping must come after it (unescaping first would turn a
    # literal &lt;w:p&gt; into a tag the stripper would then delete).
    xml = _strip_tracked_changes(xml)
    for pattern in _DOCX_FIELD_RES:
        xml = pattern.sub(" ", xml)
    xml = _DOCX_TAB_RE.sub(" ", xml)
    xml = _DOCX_PARA_BREAK_RE.sub("</w:p>\n\n", xml)
    text = _DOCX_TAG_RE.sub("", xml)
    text = html.unescape(text)
    # Normalize whitespace but keep the blank line that marks a paragraph break.
    text = "\n".join(line.strip() for line in text.splitlines())
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


def gather_corpus_files(input_path: Path) -> list[Path]:
    """Return all readable corpus files under input_path (file or directory)."""
    if input_path.is_file():
        return [input_path]
    if not input_path.is_dir():
        return []
    files = []
    for child in sorted(input_path.rglob("*")):
        if not child.is_file():
            continue
        suffix = child.suffix.lower()
        if suffix in TEXT_SUFFIXES or suffix in DOCX_SUFFIXES:
            files.append(child)
    return files


def read_corpus(input_path: Path) -> tuple[dict[str, str], list[str]]:
    """Read every supported file under input_path.

    Returns (texts, warnings) where texts maps a display filename to its
    extracted plain text, and warnings lists files that were skipped or
    failed to parse.
    """
    texts: dict[str, str] = {}
    warnings: list[str] = []

    for path in gather_corpus_files(input_path):
        suffix = path.suffix.lower()
        try:
            if suffix in TEXT_SUFFIXES:
                texts[path.name] = path.read_text(encoding="utf-8", errors="ignore")
            elif suffix in DOCX_SUFFIXES:
                texts[path.name] = _read_docx_text(path)
        except (OSError, KeyError, zipfile.BadZipFile) as exc:
            warnings.append(f"Failed to read {path.name}: {exc}")

    if input_path.is_dir():
        for path in sorted(input_path.rglob("*")):
            if path.is_file() and path.suffix.lower() in SKIP_SUFFIXES:
                warnings.append(
                    f"Skipped {path.name}: PDF parsing requires a third-party "
                    "library not available to this stdlib-only script."
                )
    elif input_path.is_file() and input_path.suffix.lower() in SKIP_SUFFIXES:
        warnings.append(
            f"Skipped {input_path.name}: PDF parsing requires a third-party "
            "library not available to this stdlib-only script."
        )

    return texts, warnings
